"""Root fixtures shared by unit and integration tests.

Nothing here touches infrastructure: unit tests must run without PostgreSQL, Redis, etc.
"""

from __future__ import annotations

from collections.abc import Iterator
from pathlib import Path
from uuid import UUID, uuid4

import pytest

from app.core.config import Settings, get_settings
from app.shared_kernel.domain.tenant import TenantScope

#: Dotenv of the isolated test stack, generated by ``make env-test`` (may be absent).
TEST_ENV_FILE = Path(__file__).resolve().parents[1] / ".env.test"


@pytest.fixture(scope="session")
def settings() -> Settings:
    """Settings of the test stack: ``.env.test`` when present, otherwise the defaults.

    Real environment variables (``make test-integration`` exports ``POSTGRES_HOST`` /
    ``POSTGRES_PORT`` etc.) take precedence over the dotenv file - the standard
    pydantic-settings source order (init > env > dotenv > defaults).
    """
    if TEST_ENV_FILE.is_file():
        return Settings(_env_file=TEST_ENV_FILE)
    return Settings()


@pytest.fixture(autouse=True)
def _clear_settings_cache() -> Iterator[None]:
    """Keep the ``get_settings()`` ``lru_cache`` from leaking between tests."""
    get_settings.cache_clear()
    yield
    get_settings.cache_clear()


@pytest.fixture(autouse=True)
def _pristine_faststream_logger() -> None:
    """Importing FastStream configures its module-level ``faststream`` logger (own stderr
    handler, ``propagate=False``). Production code never logs through it (the broker gets
    ``logger=`` from ``build_rabbit_broker``), but tests that use the name do - reset it."""
    import logging

    log = logging.getLogger("faststream")
    log.handlers.clear()
    log.propagate = True
    log.setLevel(logging.NOTSET)


@pytest.fixture
def tenant() -> UUID:
    """A fresh tenant id."""
    return uuid4()


@pytest.fixture
def tenant_scope(tenant: UUID) -> TenantScope:
    """Tenant context of the test's own tenant."""
    return TenantScope(tenant)


@pytest.fixture
def other_tenant_scope() -> TenantScope:
    """Context of a foreign tenant, for isolation tests."""
    return TenantScope(uuid4())
